maya-exp01c-20261029-025450-005.command:
mkdir -p ~/tablebook && cd ~/tablebook && cat > README.md <<'EOF'
# TableBook

Small, self-contained reservation page for family-run restaurants: a static HTML/CSS/JS site with a booking form, a live "tables left tonight" widget, and a waitlist. Built to be hosted free and edited by non-technical owners.

Status: prototype. Pages: index.html (booking form + availability widget), styles.css, app.js.
EOF
cat > index.html <<'EOF'
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>TableBook Demo</title>
<link rel="stylesheet" href="styles.css"></head>
<body>
<header><h1>Demo Kitchen</h1><p id="avail">Checking tables...</p></header>
<form id="booking">
  <label>Name <input name="name" required></label>
  <label>Party size <input name="party" type="number" min="1" max="12" value="2" required></label>
  <label>Time <select name="time"><option>5:30</option><option>6:00</option><option>7:00</option><option>8:00</option></select></label>
  <button type="submit">Book table</button>
</form>
<p id="msg"></p>
<script src="app.js"></script>
</body></html>
EOF
cat > styles.css <<'EOF'
body{font-family:system-ui,sans-serif;max-width:480px;margin:2rem auto;padding:0 1rem}
form label{display:block;margin:.6rem 0}
button{padding:.6rem 1.2rem}
EOF
cat > app.js <<'EOF'
// Simple capacity model: 40 seats, reservations reduce availability.
const CAPACITY = 40;
const bookings = JSON.parse(localStorage.getItem("bookings") || "[]");

function seatsBooked(time) {
  return bookings.filter(b => b.time === time).reduce((s, b) => s + b.party, 0);
}

function refresh() {
  const times = ["5:30", "6:00", "7:00", "8:00"];
  document.getElementById("avail").textContent =
    times.map(t => `${t}: ${Math.max(0, CAPACITY - seatsBooked(t))} seats`).join(" | ");
}

document.getElementById("booking").addEventListener("submit", e => {
  e.preventDefault();
  const f = new FormData(e.target);
  const party = Number(f.get("party"));
  const time = f.get("time");
  if (CAPACITY - seatsBooked(time) < party) {
    document.getElementById("msg").textContent = "Sorry, that time is full. Join the waitlist?";
    return;
  }
  bookings.push({ name: f.get("name"), party, time });
  localStorage.setItem("bookings", JSON.stringify(bookings));
  document.getElementById("msg").textContent = `Booked ${party} at ${time}. See you soon!`;
  refresh();
});
refresh();
EOF
git init -q -b main && git add . && git -c user.email=maya@example.com -c user.name=Maya commit -qm "TableBook prototype: booking form, capacity widget" && git push -q http://gitea:3000/maya-exp01c-20261029-025450-005/tablebook.git main 2>&1; git log --oneline | head -1

